    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(address recipient, address other) public {
        require(recipient != address(0));
        require(other != address(0));
        require(other != recipient);

        c.getFirstWithdrawalBonus(recipient); if (__ESBMC_reverted()) return;

        bool reverted;
        c.getFirstWithdrawalBonus(recipient); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(reverted);
    }

    receive() external payable {}
}

